<script setup>
import { computed, onMounted, reactive, ref } from 'vue'
import { useQuasar } from 'quasar'
import { api } from 'boot/axios'
const props=defineProps({affiliateId:{type:String,default:''}})
const $q=useQuasar(), all=ref([]), affiliates=ref([]), loading=ref(false), dialog=ref(false)
const blank=()=>({_id:'',title:'',description:'',affiliateId:props.affiliateId,discountType:'percent',discountValue:10,commissionType:'percent',commissionValue:10,active:true}),form=reactive(blank())
const headers=()=>({headers:{Authorization:'Bearer '+localStorage.getItem('aito_admin_token')}})
const rows=computed(()=>props.affiliateId?all.value.filter(r=>r.affiliate?._id===props.affiliateId):all.value)
const types=[{label:'Percentual (%)',value:'percent'},{label:'Valor fixo (R$)',value:'fixed'}]
const value=(kind,n)=>kind==='percent'?n+'%':Number(n).toLocaleString('pt-BR',{style:'currency',currency:'BRL'})
const columns=[{name:'title',label:'Cupom',field:'title',align:'left'},{name:'affiliate',label:'Afiliado',field:r=>r.affiliate?.name||'—',align:'left'},{name:'discount',label:'Desconto',field:r=>value(r.discountType,r.discountValue)},{name:'commission',label:'Comissão',field:r=>value(r.commissionType,r.commissionValue)},{name:'active',label:'Status',field:r=>r.active?'Ativo':'Pausado'},{name:'actions',label:'',align:'right'}]
const required=v=>Boolean(String(v??'').trim())||'Informe este campo.'
function open(row){Object.assign(form,blank(),row||{},row?{affiliateId:row.affiliate?._id||props.affiliateId}:{});dialog.value=true}
function error(e){$q.notify({type:'negative',message:e.response?.data?.message||'Não foi possível salvar o cupom.'})}
async function load(){loading.value=true;try{const [c,a]=await Promise.all([api.get('/admin/coupons',headers()),api.get('/admin/affiliates',headers())]);all.value=c.data.data||[];affiliates.value=a.data.data||[]}catch(e){error(e)}finally{loading.value=false}}
async function save(){loading.value=true;try{const body={title:form.title,description:form.description,affiliateId:form.affiliateId,discountType:form.discountType,discountValue:form.discountValue,commissionType:form.commissionType,commissionValue:form.commissionValue,active:form.active};if(form._id)await api.put('/admin/coupons/'+form._id,body,headers());else await api.post('/admin/coupons',body,headers());dialog.value=false;await load();$q.notify({type:'positive',message:'Cupom do kit salvo.'})}catch(e){error(e)}finally{loading.value=false}}
function remove(row){$q.dialog({title:'Pausar cupom',message:'Novas compras não poderão usar '+row.title+'. As vendas já confirmadas serão preservadas.',cancel:true,persistent:true}).onOk(async()=>{try{await api.delete('/admin/coupons/'+row._id,headers());await load()}catch(e){error(e)}})}
onMounted(load)
</script>
<template><section class="coupon-manager"><header><div><small>KIT AITONOTIFY + WHATSAPP BOTBUILDER</small><h2>Cupons e comissões</h2></div><q-btn unelevated no-caps color="teal-8" icon="mdi-plus" label="Novo cupom" @click="open()"/></header><q-banner rounded class="bg-teal-1 text-teal-10">O desconto usa o preço atual do kit no momento do checkout. A comissão percentual usa o valor pago após o desconto. Valores fixos não ultrapassam o valor da venda.</q-banner><q-table flat bordered wrap-cells row-key="_id" :rows="rows" :columns="columns" :loading="loading" no-data-label="Nenhum cupom do kit"><template #body-cell-actions="p"><q-td :props="p"><q-btn flat round dense icon="mdi-pencil-outline" aria-label="Editar cupom" @click="open(p.row)"/><q-btn flat round dense color="negative" icon="mdi-pause-circle-outline" aria-label="Pausar cupom" @click="remove(p.row)"/></q-td></template></q-table><q-dialog v-model="dialog" persistent><q-card class="coupon-dialog"><q-card-section class="row justify-between items-center"><strong>{{form._id?'Editar cupom':'Novo cupom'}}</strong><q-btn flat round dense icon="mdi-close" v-close-popup/></q-card-section><q-form @submit.prevent="save"><q-card-section class="q-gutter-md"><q-input v-model.trim="form.title" outlined label="Código do cupom" maxlength="30" counter hint="Até 30 letras, números, _ ou -." :rules="[required,v=>/^[A-Za-z0-9_-]{1,30}$/.test(v)||'Use um código válido.']"/><q-select v-model="form.affiliateId" outlined label="Afiliado" :options="affiliates.map(a=>({label:a.name+' · '+a.email,value:a._id}))" emit-value map-options :rules="[required]"/><div class="coupon-pair"><q-select v-model="form.discountType" outlined label="Tipo de desconto" :options="types" emit-value map-options/><q-input v-model.number="form.discountValue" outlined type="number" min="0" :max="form.discountType==='percent'?100:1000000" step="0.01" label="Desconto" :rules="[required]"/></div><div class="coupon-pair"><q-select v-model="form.commissionType" outlined label="Tipo de comissão" :options="types" emit-value map-options/><q-input v-model.number="form.commissionValue" outlined type="number" min="0" :max="form.commissionType==='percent'?100:1000000" step="0.01" label="Comissão do afiliado" :rules="[required]"/></div><q-input v-model="form.description" outlined type="textarea" autogrow maxlength="500" label="Descrição (opcional)"/><q-toggle v-model="form.active" color="teal-8" label="Cupom ativo"/></q-card-section><q-card-actions align="right"><q-btn flat no-caps label="Cancelar" v-close-popup/><q-btn unelevated no-caps color="teal-8" type="submit" label="Salvar cupom" :loading="loading"/></q-card-actions></q-form></q-card></q-dialog></section></template>
<style scoped>.coupon-manager{display:grid;gap:20px;color:#214d38}.coupon-manager header{display:flex;gap:15px;align-items:center;justify-content:space-between}.coupon-manager small{font-size:9px;letter-spacing:.1em;color:#438c6b}.coupon-manager h2{font-size:25px;font-weight:760;margin:8px 0;line-height:1.3}.coupon-manager .q-banner{font-size:12px;line-height:1.8}.coupon-manager :deep(.q-table__container){background:#fff;color:#315b43;border-color:#cce5d5;border-radius:14px}.coupon-dialog{width:min(620px,95vw);border-radius:20px;color:#234d38;background:#f6fcf8}.coupon-pair{display:grid;grid-template-columns:1fr 1fr;gap:12px}@media(max-width:600px){.coupon-manager header{align-items:start;flex-direction:column}.coupon-pair{grid-template-columns:1fr}}</style>
